INSERT INTO "ContentPage" ("id", "slug", "title", "category", "summary", "contentHtml", "published", "sortOrder", "publishedAt", "updatedAt") VALUES
('cms_legal_about', 'about', '关于我们', '法律与品牌', '了解 Xinyue AI 的产品定位、原则与联系方式。', '<h2 id="product">我们的产品</h2><p>Xinyue AI 将对话、图片生成、商品视觉、办公任务、项目资料和 API 使用集中在同一个工作空间。</p><h2 id="principles">产品原则</h2><p>我们围绕可控、透明和实用设计产品，让模型能力、费用、数据设置和任务状态对用户清晰可见。</p><ul><li>常用操作直接、稳定并可恢复。</li><li>模型能力、计费规则和数据边界保持透明。</li><li>个人与团队使用一致的资产管理体系。</li></ul><h2 id="responsibility">负责任地使用 AI</h2><p>生成式 AI 可能产生不准确、遗漏或不适当的内容。医疗、法律、金融、安全及其他高影响场景应由具备资质的人员独立核验。</p><h2 id="contact">联系我们</h2><p>业务合作、权利通知、隐私请求或产品支持，请通过站点公布的官方客服渠道联系。</p>', true, 10, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('cms_legal_copyright', 'copyright', '版权说明', '法律与品牌', '明确平台内容、第三方软件以及用户和 AI 生成内容之间的权利边界。', '<h2 id="brand">品牌与平台内容</h2><p>Xinyue AI 的名称、标识、品牌视觉、产品文案、自有界面素材和原创代码受适用的知识产权法律保护。</p><h2 id="third-party">第三方开源软件</h2><p>本产品可能使用开源软件和第三方组件。相关组件继续适用其原始许可证、NOTICE 文件和署名要求。</p><h2 id="generated">用户与生成内容</h2><p>用户保留其合法上传内容中的既有权利。AI 生成内容的权利状态取决于人工创作贡献、模型服务条款及适用法律。</p><h2 id="notice">权利通知</h2><p>权利人可通过官方客服提交权利证明、具体内容位置、联系方式和处理请求。</p>', true, 20, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('cms_legal_terms', 'terms', '用户协议', '法律与品牌', '使用 Xinyue AI 前请阅读账户、服务、计费和可接受使用规则。', '<h2 id="account">账户与访问</h2><p>用户应提供真实有效的登录信息，并妥善保护验证码、密码、API 密钥和会话。</p><h2 id="service">服务与模型</h2><p>平台可能通过自营或第三方模型渠道提供服务，模型可用性会受到供应商、网络、额度及安全策略影响。</p><h2 id="billing">套餐、创作点与退款</h2><p>套餐、试用、创作点和模型价格以购买页面展示的即时信息为准。</p><h2 id="conduct">可接受使用</h2><p>不得利用服务从事违法活动、侵犯他人权利、绕过访问控制、干扰服务或滥用试用资源。</p><h2 id="liability">输出核验</h2><p>AI 输出仅供辅助，不构成专业意见或事实保证。用户负责审查输出并决定最终用途。</p><h2 id="changes">变更与终止</h2><p>平台可能因产品、法律或安全要求更新协议，并以合理方式提示。</p>', true, 30, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP),
('cms_legal_privacy', 'privacy', '隐私政策', '法律与品牌', '说明 Xinyue AI 如何处理、保存和保护账户及内容数据。', '<h2 id="collection">我们处理的数据</h2><p>根据所用功能，平台可能处理账户信息、登录记录、对话、提示词、上传文件、生成资产、模型与计费记录以及基础运行日志。</p><h2 id="purpose">处理目的</h2><p>数据用于交付模型服务、同步历史和资产、计算费用、发送通知、排查故障、防止滥用并履行法律义务。</p><h2 id="sharing">共享与委托处理</h2><p>为完成请求，必要内容可能发送给用户选择的模型提供商、对象存储、邮件、支付或基础设施服务商。</p><h2 id="retention">保存与删除</h2><p>保存期限取决于账户设置、服务需要和法定义务。账务、安全和合规记录可能按法定期限保留。</p><h2 id="controls">你的控制权</h2><p>用户可以管理聊天历史、训练退出、分析、个性化和 API 凭据，并可导出或删除相应内容。</p><h2 id="security">安全与未成年人</h2><p>平台采用访问控制、凭据加密、审计和最小权限等措施保护数据。</p>', true, 40, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP)
